class LmdbLegacyEstimatorV2CompatibilityTest {

	private static final String FIXTURE = "/org/eclipse/rdf4j/sail/lmdb/legacy-estimator-v2/f0-v2-store-and-estimator.zip";
	private static final String FIXTURE_SHA256 = "0712f9d8b1fd42a9c2c73a709ac7a8cb626d29706ce4da9969e7948395761815";
	private static final String LEGACY_DIRECTORY = "join-estimator.rjes";
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VF.createIRI("urn:s");
	private static final IRI PREDICATE = VF.createIRI("urn:p");
	private static final IRI OBJECT = VF.createIRI("urn:o");
	private static final IRI CONTEXT = VF.createIRI("urn:legacy:context");
	private static final IRI SECOND_PREDICATE = VF.createIRI("urn:legacy:second-predicate");

	@Test
	void genuineV2CacheIsUnavailableUntilRebuiltFromItsOwnUpdatedStore(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		byte[] archive;
		try (InputStream input = getClass().getResourceAsStream(FIXTURE)) {
			assertNotNull(input, "the upstream fixture must be available");
			archive = input.readAllBytes();
		}
		assertEquals(FIXTURE_SHA256, sha256(archive));
		Path original = evidence.resolve("original-store");
		extract(archive, original, false);
		byte[] metadata = Files.readAllBytes(original.resolve(LEGACY_DIRECTORY).resolve("metadata.bin"));
		assertEquals("RJED", new String(metadata, 0, 4, StandardCharsets.US_ASCII));
		assertEquals(2, ByteBuffer.wrap(metadata, 4, Integer.BYTES).getInt());
		Map<Path, String> originalLegacyFiles = legacyFileHashes(original.resolve(LEGACY_DIRECTORY));
		assertTrue(originalLegacyFiles.size() > 1, "the fixture must contain the actual upstream sketch parts");

		// Add rows to the very store whose v2 cache was generated; the original cache can no longer be current.
		LmdbStore writer = new LmdbStore(original.toFile(), config(false));
		writer.init();
		try (NotifyingSailConnection connection = writer.getConnection()) {
			assertTrue(connection.hasStatement(SUBJECT, PREDICATE, OBJECT, false));
			connection.begin(IsolationLevels.READ_COMMITTED);
			connection.addStatement(VF.createIRI("urn:legacy:second-subject"), PREDICATE, OBJECT, CONTEXT);
			connection.addStatement(SUBJECT, SECOND_PREDICATE, VF.createIRI("urn:legacy:second-object"), CONTEXT);
			connection.commit();
		} finally {
			writer.shutDown();
		}
		assertLegacyFilesUnchanged(original.resolve(LEGACY_DIRECTORY), originalLegacyFiles);

		// Copy native data and properties after the commit, then restore the unchanged cache in a fresh directory.
		// This excludes the rebuild marker created by the new commit without deleting any fixture file.
		Path updated = evidence.resolve("updated-store");
		copyNativeStore(original, updated);
		extract(archive, updated, true);
		assertLegacyFilesUnchanged(updated.resolve(LEGACY_DIRECTORY), originalLegacyFiles);
		Path verifier = evidence.resolve("verifier");
		extract(archive, verifier, true);

		LmdbStore backing = new LmdbStore(updated.toFile(), config(false));
		backing.init();
		try (SketchBasedJoinEstimator estimator = new SketchBasedJoinEstimator(
				new LmdbSketchStatementSource(backing.getBackingStore()),
				SketchBasedJoinEstimator.Config.defaults()
						.withMemoryBudgetBytes(4L * 1024L * 1024L)
						.withColdSynopsisCapacity(64))) {
			estimator.setRebuildAllowedSupplier(() -> false);
			estimator.configurePersistence(verifier.resolve(LEGACY_DIRECTORY), true);
			assertLegacyFilesUnchanged(verifier.resolve(LEGACY_DIRECTORY), originalLegacyFiles);
			assertFalse(estimator.isReadyNonBlocking(), "v2 has no durable identity and must not be authorized");
			assertFalse(evidence(estimator, PREDICATE, null, null).usable(),
					"the stale v2 estimate must not be visible while rebuild is held");
			estimator.setRebuildAllowedSupplier(() -> true);
			assertTrue(estimator.forceFlush());
			assertRebuiltRows(estimator);
			estimator.persistIfDirty();
		} finally {
			backing.shutDown();
		}
		assertLegacyFilesUnchanged(verifier.resolve(LEGACY_DIRECTORY), originalLegacyFiles);
		assertLegacyFilesUnchanged(updated.resolve(LEGACY_DIRECTORY), originalLegacyFiles);

		// Exercise the actual store-open path separately, still with the untouched v2 cache.
		LmdbStore reopened = new LmdbStore(updated.toFile(), config(true));
		reopened.init();
		try {
			assertTrue(reopened.awaitSketchesReady(30, TimeUnit.SECONDS));
			assertTrue(reopened.forceFlushSketchEstimator());
			assertRebuiltRows(reopened.getBackingStore().getSketchBasedJoinEstimator());
			try (NotifyingSailConnection reader = reopened.getConnection()) {
				assertTrue(reader.hasStatement(SUBJECT, PREDICATE, OBJECT, false));
				assertTrue(reader.hasStatement(SUBJECT, SECOND_PREDICATE, null, false, CONTEXT));
			}
		} finally {
			reopened.shutDown();
		}
		assertLegacyFilesUnchanged(updated.resolve(LEGACY_DIRECTORY), originalLegacyFiles);
	}

	private static LmdbStoreConfig config(boolean enabled) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc").setNativeEvaluationEnabled(true)
				.setSketchEstimatorEnabled(enabled)
				.setSketchEstimatorMemoryBudgetBytes(4L * 1024L * 1024L)
				.setSketchEstimatorColdSynopsisCapacity(64);
		config.setExperimentalQueryOptimizations(true);
		return config;
	}

	private static QuadEvidence evidence(SketchBasedJoinEstimator estimator, IRI predicate, IRI object, IRI context) {
		int mask = QuadProbe.PREDICATE | (object == null ? 0 : QuadProbe.OBJECT)
				| (context == null ? 0 : QuadProbe.CONTEXT);
		return estimator.synopsisService()
				.probe(new QuadProbe(mask, QuadProbe.SUBJECT, 0L,
						QuadValueHash.hash(predicate), object == null ? 0L : QuadValueHash.hash(object),
						context == null ? 0L : QuadValueHash.hash(context), estimator.quadSnapshotIdentity()));
	}

	private static void assertRebuiltRows(SketchBasedJoinEstimator estimator) {
		QuadEvidence predicate = evidence(estimator, PREDICATE, null, null);
		QuadEvidence pair = evidence(estimator, PREDICATE, OBJECT, null);
		QuadEvidence context = evidence(estimator, PREDICATE, OBJECT, CONTEXT);
		QuadEvidence second = evidence(estimator, SECOND_PREDICATE, null, null);
		assertTrue(predicate.usable());
		assertTrue(pair.usable());
		assertTrue(context.usable());
		assertTrue(second.usable());
		assertEquals(2.0d, predicate.rows().estimate(), 0.0d);
		assertEquals(2.0d, pair.rows().estimate(), 0.0d);
		assertEquals(1.0d, context.rows().estimate(), 0.0d);
		assertEquals(1.0d, predicate.distribution()
				.orElseThrow()
				.highQualityInnerProduct(second.distribution().orElseThrow())
				.orElseThrow(), 0.0d);
	}

	private static void extract(byte[] archive, Path destination, boolean legacyOnly) throws Exception {
		Files.createDirectories(destination);
		try (ZipInputStream input = new ZipInputStream(new ByteArrayInputStream(archive))) {
			for (ZipEntry entry; (entry = input.getNextEntry()) != null;) {
				if (legacyOnly && !entry.getName().startsWith(LEGACY_DIRECTORY + "/")) {
					continue;
				}
				Path target = destination.resolve(entry.getName()).normalize();
				assertTrue(target.startsWith(destination));
				Files.createDirectories(target.getParent());
				Files.copy(input, target);
			}
		}
	}

	private static void copyNativeStore(Path source, Path destination) throws Exception {
		try (var paths = Files.walk(source)) {
			for (Path path : paths.filter(Files::isRegularFile).toList()) {
				Path relative = source.relativize(path);
				if (relative.startsWith(LEGACY_DIRECTORY) || path.getFileName().toString().equals("lock.mdb")) {
					continue;
				}
				Path target = destination.resolve(relative);
				Files.createDirectories(target.getParent());
				Files.copy(path, target);
			}
		}
	}

	private static Map<Path, String> legacyFileHashes(Path directory) throws Exception {
		Map<Path, String> hashes = new LinkedHashMap<>();
		try (var paths = Files.walk(directory)) {
			for (Path path : paths.filter(Files::isRegularFile).sorted().toList()) {
				hashes.put(directory.relativize(path), sha256(Files.readAllBytes(path)));
			}
		}
		return hashes;
	}

	private static void assertLegacyFilesUnchanged(Path directory, Map<Path, String> expected) throws Exception {
		for (Map.Entry<Path, String> entry : expected.entrySet()) {
			assertEquals(entry.getValue(), sha256(Files.readAllBytes(directory.resolve(entry.getKey()))),
					"the legacy fixture file must remain unchanged: " + entry.getKey());
		}
	}

	private static String sha256(byte[] bytes) throws Exception {
		return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
	}
}
